/* 衡山毛筆フォント削除済み */
        @font-face-REMOVED {
            font-family: 'KouzanBrushFont';
            src: url('data:font/truetype;base64,') format('truetype');
            font-weight: normal;
            font-style: normal;
        }

        :root {
            --paper-width: 420mm;
            --paper-height: 297mm;
            --gold-color: #d4af37;
        }

        body {
            font-family: "Helvetica Neue", Arial, sans-serif;
            background-color: #f0f0f0;
            margin: 0;
            display: flex;
            height: 100vh;
        }

        /* ===== 左側の操作パネル ===== */
        .controls {
            width: 300px;
            background: #333;
            color: white;
            padding: 20px;
            box-sizing: border-box;
            overflow-y: auto;
            flex-shrink: 0;
        }

        .controls h2 { margin-top: 0; font-size: 1.2rem; }

        .input-group { margin-bottom: 15px; }
        .input-group label { display: block; margin-bottom: 5px; font-size: 0.9rem; }
        .input-group input, .input-group textarea {
            width: 100%;
            padding: 8px;
            box-sizing: border-box;
            border-radius: 4px;
            border: none;
        }
        .input-group textarea { height: 100px; resize: vertical; }

        .input-notice {
            margin-top: 6px;
            padding: 7px 10px;
            background-color: #fff3cd;
            border-left: 4px solid #f0ad4e;
            border-radius: 3px;
            color: #7a5000;
            font-size: 0.78rem;
            line-height: 1.6;
        }
        .input-notice-example {
            font-weight: bold;
            letter-spacing: 0.05em;
        }

        button.print-btn {
            background-color: var(--gold-color);
            color: #000;
            border: none;
            padding: 10px 20px;
            width: 100%;
            font-weight: bold;
            cursor: pointer;
            margin-top: 20px;
        }
        button.print-btn:hover { opacity: 0.9; }

        button.pdf-btn {
            background-color: #28a745;
            color: white;
            border: none;
            padding: 10px 20px;
            width: 100%;
            font-weight: bold;
            cursor: pointer;
            margin-top: 10px;
        }
        button.pdf-btn:hover { opacity: 0.9; }
        button.pdf-btn:disabled { background-color: #ccc; cursor: not-allowed; }

        /* 個人戦 / 団体戦 モード選択 */
        .mode-select {
            display: flex;
            margin-bottom: 12px;
            border: 1px solid #555;
            border-radius: 5px;
            overflow: hidden;
        }
        .mode-select label {
            flex: 1;
            text-align: center;
            cursor: pointer;
            margin: 0;
            background: #444;
            color: #ccc;
        }
        .mode-select input { display: none; }
        .mode-select span {
            display: block;
            padding: 12px;
            font-weight: bold;
        }
        .mode-select input:checked + span {
            background: var(--gold-color);
            color: #000;
        }

        /* 個人戦サブモード（通常 / 中野杯）*/
        .sub-mode-select {
            display: flex;
            margin-bottom: 16px;
            border: 1px solid #666;
            border-radius: 5px;
            overflow: hidden;
        }
        .sub-mode-select label {
            flex: 1;
            text-align: center;
            cursor: pointer;
            margin: 0;
            background: #3a3a3a;
            color: #bbb;
        }
        .sub-mode-select input { display: none; }
        .sub-mode-select span {
            display: block;
            padding: 9px 6px;
            font-weight: bold;
            font-size: 0.85rem;
        }
        .sub-mode-select input:checked + span {
            background: #7a5c10;
            color: #fff;
        }

        /* 主催/後援 切替 */
        .organizer-type-select {
            display: flex;
            margin-bottom: 8px;
            border: 1px solid #555;
            border-radius: 5px;
            overflow: hidden;
        }
        .organizer-type-select label {
            flex: 1;
            text-align: center;
            cursor: pointer;
            margin: 0;
            background: #444;
            color: #ccc;
        }
        .organizer-type-select input { display: none; }
        .organizer-type-select span {
            display: block;
            padding: 8px;
            font-weight: bold;
            font-size: 0.9rem;
        }
        .organizer-type-select input:checked + span {
            background: var(--gold-color);
            color: #000;
        }

        /* フォント選択 */
        .font-select-group {
            margin-bottom: 16px;
        }
        .font-select-group label {
            display: block;
            margin-bottom: 8px;
            font-size: 0.9rem;
        }
        .font-options {
            display: flex;
            flex-direction: column;
            gap: 6px;
        }
        .font-option {
            display: flex;
            align-items: center;
            gap: 10px;
            padding: 8px 10px;
            background: #444;
            border-radius: 5px;
            cursor: pointer;
            border: 2px solid transparent;
            transition: border-color 0.2s, background 0.2s;
        }
        .font-option:hover { background: #555; }
        .font-option input[type="radio"] { display: none; }
        .font-option.selected {
            border-color: var(--gold-color);
            background: #4a3a00;
        }
        .font-option-preview {
            font-size: 1.3rem;
            color: #fff;
            line-height: 1;
            flex-shrink: 0;
            writing-mode: horizontal-tb;
        }
        .font-option-name {
            font-size: 0.75rem;
            color: #bbb;
            line-height: 1.3;
        }
        .font-option.selected .font-option-name { color: #f0d060; }

        /* 中野杯専用バッジ */
        .nakano-badge {
            display: inline-block;
            background: #7a5c10;
            color: #fff;
            font-size: 0.75rem;
            padding: 3px 8px;
            border-radius: 3px;
            margin-bottom: 8px;
            letter-spacing: 0.05em;
        }

        /* ===== 右側のプレビューエリア ===== */
        .preview-area {
            flex-grow: 1;
            display: flex;
            padding: 40px;
            overflow: auto;
        }

        .preview-outer {
            margin: auto;
            overflow: hidden;
            flex-shrink: 0;
        }

        .preview-wrapper {
            transform-origin: top left;
        }

        /* ===== 賞状本体 ===== */
        .certificate {
            width: var(--paper-width);
            height: var(--paper-height);
            background: white;
            box-shadow: 0 0 15px rgba(0,0,0,0.2);
            position: relative;
            writing-mode: vertical-rl;
            text-orientation: upright;
            font-family: 'Yuji Syuku', serif;
            box-sizing: border-box;
            padding: 40mm 50mm;
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        .border-frame {
            position: absolute;
            top: 0; bottom: 0; left: 0; right: 0;
            background-image: url('resize_crop_A3-h-n_27dpi_A4.jpeg');
            background-size: 100% 100%;
            pointer-events: none;
            z-index: 0;
        }

        .cert-title {
            font-size: 4rem;
            font-weight: 700;
            margin-left: 20mm;
            letter-spacing: 1rem;
            position: relative;
            z-index: 1;
        }

        .cert-rank {
            font-size: 3.5rem;
            font-weight: bold;
            margin-left: 10mm;
            align-self: flex-start;
            padding-top: 20mm;
            position: relative;
            z-index: 1;
            letter-spacing: 0.5rem;
            writing-mode: vertical-rl;
            text-orientation: upright;
        }

        .cert-department {
            display: none;
            font-size: 2rem;
            font-weight: bold;
            margin-left: 10mm;
            align-self: flex-start;
            padding-top: 20mm;
            position: relative;
            z-index: 1;
            letter-spacing: 0.5rem;
        }

        .rank-recipient-wrapper {
            display: flex;
            writing-mode: horizontal-tb;
            flex-direction: column;
            align-items: center;
            gap: 10mm;
            margin-left: 20mm;
            z-index: 1;
        }

        .rank-recipient-wrapper .cert-rank,
        .rank-recipient-wrapper .recipients-container {
            align-self: auto;
            margin: 0;
            padding: 0;
        }

        .certificate.has-department .cert-department { display: block; }

        .certificate.has-department .rank-recipient-wrapper {
            justify-content: space-between;
            align-self: stretch;
            margin-left: 10mm;
            margin-right: 5mm;
            gap: 0;
        }

        .certificate.has-department .cert-rank {
            font-size: 3.5rem;
            padding-top: 20mm;
        }

        .certificate.has-department .cert-body {
            transform: translateX(20mm);
        }

        .certificate:not(.has-department):not(.team-mode) .rank-recipient-wrapper {
            gap: 30mm;
            transform: translateY(10mm);
        }

        .certificate:not(.has-department):not(.team-mode):not(.long-tournament) .cert-body {
            transform: translateX(10mm);
        }

        .recipients-container {
            display: flex;
            writing-mode: vertical-rl;
            text-orientation: upright;
            flex-direction: column;
            gap: 20px;
            align-items: center;
        }

        .certificate.team-mode .recipients-container { margin-top: 15mm; }

        .certificate.team-mode .cert-rank,
        .certificate.team-mode .cert-team { margin-top: 10mm; }

        .cert-recipient {
            font-size: 4.5rem;
            font-weight: bold;
            letter-spacing: 0.5rem;
            white-space: nowrap;
            writing-mode: vertical-rl;
            text-orientation: upright;
        }
        .cert-recipient span { margin-top: 20px; }

        .certificate.long-tournament .cert-rank,
        .certificate.long-tournament .recipients-container,
        .certificate.long-tournament .cert-department,
        .certificate.long-tournament .cert-team { transform: translateX(15mm); }

        .certificate.long-tournament .cert-body { transform: translateX(25mm); }
        .certificate.long-tournament .cert-footer { transform: translateX(25mm); }

        .certificate.long-tournament.has-department .cert-footer { transform: translateX(35mm); }
        .certificate.long-tournament.has-department .cert-date { transform: translateX(-10mm); }

        .certificate.multi-recipients .cert-recipient { font-size: 3.0rem; }
        .certificate.multi-recipients .rank-recipient-wrapper { transform: translateX(10mm); }
        .certificate.multi-recipients .cert-footer { transform: translateX(15mm); }
        .certificate.multi-recipients .cert-body { transform: translateX(25mm); }

        .certificate.long-tournament.multi-recipients .cert-footer { transform: translateX(30mm); }
        .certificate.long-tournament.multi-recipients .cert-body { transform: translateX(40mm); }

        .certificate.three-recipients .cert-footer { transform: translateX(35mm); }
        .certificate.three-recipients .cert-body { transform: translateX(35mm); }

        .certificate.long-tournament.three-recipients .cert-body,
        .certificate.long-tournament.three-recipients .cert-footer { transform: translateX(50mm); }

        .cert-team {
            font-size: 3.0rem;
            font-weight: bold;
            letter-spacing: 0.3rem;
            white-space: nowrap;
            writing-mode: vertical-rl;
            text-orientation: upright;
        }

        .cert-body {
            font-size: 3.5rem;
            font-weight: bold;
            line-height: 2.0;
            white-space: pre-wrap;
            text-align: justify;
            margin: 30mm 15mm 0 auto;
            position: relative;
            z-index: 1;
            letter-spacing: 0.3rem;
            max-height: 200mm;
            align-self: flex-start;
        }

        .cert-footer {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            gap: 15mm;
            position: relative;
            z-index: 1;
            transform: translateX(5mm);
            flex-grow: 1;
            align-self: stretch;
        }

        .cert-date {
            font-size: 2.5rem;
            letter-spacing: 0.3rem;
            white-space: nowrap;
            align-self: flex-start;
            margin-top: 20mm;
            position: relative;
            z-index: 1;
        }

        .cert-organization {
            font-size: 3.0rem;
            font-weight: bold;
            letter-spacing: 0.3rem;
            white-space: nowrap;
            align-self: center;
        }

        .cert-sender {
            font-size: 3rem;
            letter-spacing: 0.3rem;
            white-space: nowrap;
            align-self: center;
            margin-top: 60mm;
        }

        .certificate.has-department:not(.team-mode) .cert-sender,
        .certificate.team-mode .cert-sender { transform: translateX(8mm); }

        .certificate.multi-recipients .cert-organization { transform: translateX(5mm); }
        .certificate.multi-recipients .cert-sender { transform: translateX(13mm); }

        /* ===== 印刷 ===== */
        @media print {
            @page { size: A3 landscape; margin: 0; }
            * {
                -webkit-print-color-adjust: exact !important;
                print-color-adjust: exact !important;
            }
            html, body {
                width: var(--paper-width);
                height: var(--paper-height);
                margin: 0; padding: 0;
                overflow: hidden;
                background: white;
                display: block !important;
            }
            .controls { display: none !important; }
            .panel-toggle-btn { display: none !important; }
            .preview-area {
                display: block; padding: 0; margin: 0;
                width: var(--paper-width);
                height: var(--paper-height);
                overflow: hidden;
            }
            .preview-outer {
                width: var(--paper-width) !important;
                height: var(--paper-height) !important;
                margin: 0 !important;
                overflow: hidden;
            }
            .preview-wrapper {
                transform: none !important;
                width: var(--paper-width) !important;
                height: var(--paper-height) !important;
                margin: 0 !important;
                overflow: hidden;
            }
            .certificate {
                box-shadow: none;
                width: var(--paper-width);
                height: var(--paper-height);
                margin: 0; overflow: hidden;
                page-break-after: avoid;
                break-after: avoid;
            }
            .border-frame { display: none !important; }
        }

        /* ===== モバイル ===== */
        .panel-toggle-btn { display: none; }

        @media (max-width: 768px) {
            body { flex-direction: column; height: 100dvh; overflow: hidden; }

            .panel-toggle-btn {
                display: flex;
                align-items: center;
                gap: 8px;
                position: fixed;
                top: 12px; right: 12px;
                z-index: 100;
                background: var(--gold-color);
                color: #000;
                border: none;
                border-radius: 6px;
                padding: 8px 14px;
                font-size: 0.85rem;
                font-weight: bold;
                cursor: pointer;
                box-shadow: 0 2px 8px rgba(0,0,0,0.3);
            }

            .panel-toggle-btn .btn-icon { font-size: 1.1rem; line-height: 1; }

            .controls {
                position: fixed;
                top: 0; left: 0; right: 0; bottom: 0;
                width: 100%;
                z-index: 90;
                transform: translateY(-100%);
                transition: transform 0.3s ease;
                padding: 16px 16px 100px 16px;
                border-radius: 0;
            }

            .controls.panel-open { transform: translateY(0); }

            .controls h2 {
                font-size: 1.1rem;
                margin-top: 8px; margin-bottom: 12px;
                padding-top: 40px;
            }

            .input-group { margin-bottom: 12px; }

            .input-group input,
            .input-group textarea { font-size: 16px; padding: 10px; }

            .mode-select span { padding: 10px; font-size: 0.9rem; }

            .input-notice {
                margin-top: 6px; padding: 7px 10px;
                background-color: #fff3cd;
                border-left: 4px solid #f0ad4e;
                border-radius: 3px;
                color: #7a5000;
                font-size: 0.78rem;
                line-height: 1.6;
            }
            .input-notice-example { font-weight: bold; letter-spacing: 0.05em; }

            button.print-btn { padding: 14px; font-size: 1rem; margin-top: 10px; }

            .preview-area {
                flex-grow: 1; padding: 12px;
                overflow: hidden;
                display: flex;
                align-items: center;
                justify-content: center;
            }

            .preview-outer { margin: 0; }
        }

        @media (max-width: 480px) {
            .preview-area { padding: 8px; }
        }
